const assert=require('node:assert/strict')
const fs=require('node:fs')
const ts=require('typescript')
const mod={exports:{}}
new Function('module','exports',ts.transpileModule(
 fs.readFileSync('lib/vendaInstalacaoProducao.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}
).outputText)(mod,mod.exports)
const {disponibilidadePeca,validarRegistroInstalacao}=mod.exports
const ordem=(status,quantidade,parcial)=>({item_ref:'marco-1',tipo_producao:'esquadria',status,quantidade,quantidade_produzida:parcial,bloqueada:false})
// A mesma OP tem 4 peças: 2 conferidas, 2 aguardando fabricação.
const disponibilidade=disponibilidadePeca([ordem('conferencia',4,2)],'marco-1',4)
assert.equal(disponibilidade.prontas,2)
assert.equal(disponibilidade.faltantes,2)
assert.equal(disponibilidade.estado,'parcial')
assert.equal(validarRegistroInstalacao({existente:0,novo:2,status:'em_instalacao',quantidadePlanejada:4,disponibilidade}),null)
assert.match(validarRegistroInstalacao({existente:0,novo:3,status:'em_instalacao',quantidadePlanejada:4,disponibilidade}),/Produção insuficiente/)
assert.match(validarRegistroInstalacao({existente:2,novo:4,status:'instalado',quantidadePlanejada:4,disponibilidade}),/Produção insuficiente/)
// Mesmo se o status da OP for indevidamente concluída, o parcial é a fonte da verdade.
assert.equal(disponibilidadePeca([ordem('concluida',4,2)],'marco-1',4).prontas,2)
assert.equal(disponibilidadePeca([ordem('concluida',4,null)],'marco-1',4).prontas,4)
assert.equal(disponibilidadePeca([ordem('conferencia',4,0)],'marco-1',4).prontas,0)
assert.equal(disponibilidadePeca([{...ordem('conferencia',4,2),bloqueada:true}],'marco-1',4).prontas,0)
assert.equal(disponibilidadePeca([ordem('em_producao',4,2)],'marco-1',4).prontas,0)
assert.equal(disponibilidadePeca([ordem('cancelada',4,2)],'marco-1',4).prontas,0)
assert.equal(disponibilidadePeca([ordem('conferencia',4,4)],'marco-1',4).prontas,4)
assert.equal(disponibilidadePeca([ordem('conferencia',4,2),ordem('conferencia',4,1)],'marco-1',8).prontas,3)
const migration=fs.readFileSync('supabase/migrations/20261013161132_ordens_producao_unidades_parciais_v1_20261013.sql','utf8')
assert.match(migration,/unique\(ordem_id,indice\)/)
assert.match(migration,/p_empresa uuid,p_ordem uuid,p_indices integer\[\]/)
assert.match(migration,/if v\.bloqueada/)
assert.match(migration,/v\.status<>'conferencia'/)
assert.match(migration,/v_prontas=v_qtd then 'concluida' else 'conferencia'/)
assert.match(migration,/new\.quantidade_produzida<new\.quantidade/)
const route=fs.readFileSync('app/api/producao/ordens/unidades/route.ts','utf8')
assert.match(route,/usuarioPodeAcaoServer/)
assert.match(route,/minimo:edicao\?'edicao':'consulta'/)
assert.match(route,/\.eq\('empresa_id',usuario\.empresa_id\)/)
const ui=fs.readFileSync('app/producao/page.tsx','utf8')
assert.match(ui,/Confirmar.*unidade\(s\) produzida\(s\)/)
assert.match(ui,/setSelecionadasUnidades/)
const install=fs.readFileSync('components/clientes/VendaInstalacaoDetalhada.tsx','utf8')
assert.match(install,/Kanban de instalação por peça/)
assert.match(install,/quantidade_instalada/)
console.log('PASS: produção parcial 2/4, escopo do card, instalação limitada, gates, legados e Kanban.')
